select id, session_id, page, duration_sec, percent_rank() over (order by duration_sec nulls last) duration_sec_percent_rank, dense_rank() over (order by duration_sec nulls first) duration_sec_dense_rank, cume_dist() over (partition by page, session_id order by duration_sec nulls last) duration_sec_cume_dist, lag(duration_sec, 1) over (partition by event_type, session_id order by duration_sec, id) prev_duration_sec from web_events
